import{_ as i,a0 as p,w as s,s as d,I as l,x as a,a1 as r,A as n,ao as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"发展中国家面临的三个关键开源挑战 | LCTT x X-CMD","titleTemplate":false,"description":"发展中国家面临的三个关键开源挑战 | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"发展中国家面临的三个关键开源挑战 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"发展中国家面临的三个关键开源挑战 | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20230427.2 ⭐️⭐️ 3 key open source challenges in developing countries","title":"发展中国家面临的三个关键开源挑战","tag":"202307","desc":""},"relativePath":"202307/20230427.2 ⭐️⭐️ 3 key open source challenges in developing countries.md","filePath":"[post].md"}'),u={name:"202307/20230427.2 ⭐️⭐️ 3 key open source challenges in developing countries.md"};function h(m,e,f,b,x,T){const t=p("Link");return s(),d("div",null,[e[22]||(e[22]=l("h1",{id:"发展中国家面临的三个关键开源挑战",tabindex:"-1"},[a("发展中国家面临的三个关键开源挑战 "),l("a",{class:"header-anchor",href:"#发展中国家面临的三个关键开源挑战","aria-label":"Permalink to “发展中国家面临的三个关键开源挑战”"},"​")],-1)),e[23]||(e[23]=l("p",null,[l("img",{src:"https://img.linux.net.cn/data/attachment/album/202307/27/073634a244fon440y25kug.jpg",alt:""})],-1)),e[24]||(e[24]=l("blockquote",null,[l("p",null,"开源在发展中国家面临着许多困难，这些困难使人们对开源的看法以及与开源的联系变得不准确、不贴切。")],-1)),e[25]||(e[25]=l("blockquote",null,[l("p",null,"编者按：本文作者 Ahmed Sobeh 是 Aiven 开源项目办公室的开源工程经理。他来自埃及，在开源领域有各种经验。本文是他对埃及的开源文化的见解。")],-1)),l("p",null,[e[2]||(e[2]=a("当我回国，和科技行业或其他行业的人谈起我的工作和我每天参与的话题时，我通常会对 ",-1)),l("ruby",null,[r(t,{href:"https://opensource.com/article/20/5/open-source-program-office"},{default:n(()=>[...e[0]||(e[0]=[a("开源计划办公室",-1)])]),_:1}),e[1]||(e[1]=l("rt",null,"Open Source Programs Office",-1))]),e[3]||(e[3]=a("（OSPO）这个想法感到困惑。一家公司在没有明显的直接经济利益的情况下为开源项目做出贡献，这种概念在文化上很难理解或解释。",-1))]),e[26]||(e[26]=o('<p>作为一个在发展中国家出生并成长的人，我理解并赞同这个观点。曾几何时，我对开源软件的唯一理解是，它是一种无需付费、无需等待特定问题或附加功能发布即可使用的软件。我可以自己在本地做任何我需要的事情。</p><p>在发展中国家，开源面临着许多困难，这些困难使人们对它的看法和相关印象变得不准确和脱节。我将在本文中讨论这些问题。</p><h3 id="发展中国家的开源挑战" tabindex="-1">发展中国家的开源挑战 <a class="header-anchor" href="#发展中国家的开源挑战" aria-label="Permalink to “发展中国家的开源挑战”">​</a></h3><p>开源在这些地区面临的挑战主要分为三个部分：</p><ul><li>社会与文化</li><li>资源与基础设施</li><li>政府管理</li></ul><h3 id="社会与文化" tabindex="-1">社会与文化 <a class="header-anchor" href="#社会与文化" aria-label="Permalink to “社会与文化”">​</a></h3><p>众所周知，科技中的文化，特别是其中的开源部分，源自它所存在的社会文化。这就是为什么在当今世界，开源更有可能在世界较发达地区得到维持和维护。</p><p>但是，试想一个完美的社会，一个最适合开源发展、维持和维护的社会。这个社会的文化是什么样的？其主要特征是什么？</p><h4 id="开放和透明" tabindex="-1">开放和透明 <a class="header-anchor" href="#开放和透明" aria-label="Permalink to “开放和透明”">​</a></h4><p>开源想要发展，社会文化必须尽可能开放和透明。信息必须可以自由公开地获取，这在许多欠发达地区是一个巨大的问题。信息往往受到繁文缛节的制约，普通公民难以获取，更不用说那些试图为开源做出贡献的人了。</p><h4 id="自由" tabindex="-1">自由 <a class="header-anchor" href="#自由" aria-label="Permalink to “自由”">​</a></h4><p>“自由”这个词有许多不同的含义与解释。有言论自由、表达自由、选择自由、信仰自由、宗教自由等等。在本文中，我最关心的自由方面是在没有更高层机构干预的情况下建立新社区和组织的能力。这是开源的本质。分布式协作模式是一种高效的协作模式，在这种模式下，大型团体在没有强大的中央权威指挥的情况下开展合作。这是大多数这些地区面临的另一个重大挑战。新的社区和组织往往会受到质疑、密切监视，不幸的是，在某些情况下，甚至会因为害怕可能出现的新思想或其他原因而遭到起诉并最终被关闭。</p><h4 id="充满活力" tabindex="-1">充满活力 <a class="header-anchor" href="#充满活力" aria-label="Permalink to “充满活力”">​</a></h4><p>充满活力的文化对开源的发展至关重要。准备接受和实行新想法的文化是发展开源最理想的地方。抵制改变和倾向于固守传统方法会阻止社会接受新的技术和方法，这是大部分发展中国家中的主要问题。</p><p>这些地区抵制改变背后最重要也是最常见的原因是对未知的恐惧。把对未知的恐惧作为“发展中国家”的问题来讨论是不公平的。这是在哪里都常见问题，甚至在发达国家。但是恐惧背后的一些原因是发展中国家特有的。主要原因有两个，一是对科技行业的能力缺乏信心，二是缺乏责任感。企业和个人都不信任现有软件解决方案的功能，更不用说开源解决方案了。有一种观点认为，开源软件不安全、不可靠。当人们不相信软件开发者的能力时这种担忧会被放大。其次，人们不相信该系统会对使用软件或法律冲突中可能出现的错误或问题追究责任。</p><h3 id="资源、基础设施和经济" tabindex="-1">资源、基础设施和经济 <a class="header-anchor" href="#资源、基础设施和经济" aria-label="Permalink to “资源、基础设施和经济”">​</a></h3><p>经济挑战是发展中国家开源面临的最明显的困难，影响着这些地区的开源开发者和社区。</p><h4 id="供应和资金" tabindex="-1">供应和资金 <a class="header-anchor" href="#供应和资金" aria-label="Permalink to “供应和资金”">​</a></h4><p>开源开发人员在发展中国家努力解决供应问题。无论是上网还是使用设备，当你每天都在努力获取资源时，就很难成为一名固定的开源贡献者。这些国家的数字鸿沟十分巨大。依然有许多地区没有正常、稳定和高速的互联网连接。在设备方面，这些地区也与世界其他地区存在市场差距。没有足够的资金购买最新、最强大的机器始终是个难题，但同时也存在供应问题。在这些地区，建立和运行最大的开源项目所需的现代化、功能强大的技术设备并不总能提供。</p><p>这些问题使得自我教育和学习具有挑战性。由于这些供应问题，开源开发人员很难选择一个开源项目，自行学习所有相关知识，并开始为其做出贡献。</p><p>在这种情况下，如何建立开源社区呢？项目最终只能由少数拥有稳定高速互联网连接和最新设备的特权人士来维护。剩下的将是零星的、偶尔来自他人的贡献，很难被视为一个社区。一旦出现有偿工作的机会，即使是这些人也会消失。我亲眼见过多次这种情况。有人会开始了解一个开源项目，研究特定的堆栈或提高自己的技能，并开始为其做出贡献。但一旦出现了有偿工作的机会，即使是作为第二份工作，他们也会完全放弃开源项目。这是有道理的。任何个人都必须优先考虑自己和家人的生存手段。</p><p>这种资源匮乏和对少数特权人群的依赖，也使其几乎不可能为营销活动、社区建设活动以及最后但并非最不重要的文献本地化尝试提供资金。</p><h4 id="本地化" tabindex="-1">本地化 <a class="header-anchor" href="#本地化" aria-label="Permalink to “本地化”">​</a></h4>',23)),l("p",null,[e[5]||(e[5]=a("英语是互联网语言，但对许多国家来说并非如此。虽然几乎所有的开发人员都会说基本的英语，但并不是每个人都有能力理解文档、架构资源和技术规范，使他们能够有意义地 ",-1)),r(t,{href:"https://opensource.com/article/22/3/contribute-open-source-2022"},{default:n(()=>[...e[4]||(e[4]=[a("为开源项目做出贡献",-1)])]),_:1}),e[6]||(e[6]=a("。由于没有相应的文档，发展中国家的开发人员很难找到进入开源项目的切入点。为此所需的时间和资源通常会使这些地区的潜在贡献者望而却步。",-1))]),e[27]||(e[27]=o('<h4 id="员工合同" tabindex="-1">员工合同 <a class="header-anchor" href="#员工合同" aria-label="Permalink to “员工合同”">​</a></h4><p>几乎所有的软件员工合同都旨在将开发人员的每一行代码、贡献或想法货币化。任何参与外部项目的行为都会受到雇佣公司的质疑，而雇佣公司往往会阻止开发人员为开源做贡献，以避免法律问题。法律偏向于公司和组织，阻止软件开发人员做出外部贡献。</p><h4 id="知识产权法" tabindex="-1">知识产权法 <a class="header-anchor" href="#知识产权法" aria-label="Permalink to “知识产权法”">​</a></h4><p>发展中国家的法律框架往往不具备处理知识产权和开源许可细微差别的能力。与发达国家相比，发展中国家的知识产权法律可能较弱或不够全面，执法效力也可能较低。这可能使创作者和贡献者难以保护自己的作品，并防止他人在未经许可的情况下使用。</p><p>此外，开源许可证可能很复杂。许多发展中国家可能不具备有效驾驭这些许可的法律专业知识或资源。这可能使开发人员很难在不无意中违反许可证条款的情况下为开源项目做出贡献。</p><p>另一个问题是，知识产权法和开源许可证有时被视为发展中国家创新和发展的障碍。批评者认为，这些法律和许可会扼杀创造力，阻碍知识和技术的传播，尤其是在资源和技术有限的地区。</p><p>总体而言，发展中国家围绕知识产权法和开源贡献所面临的挑战是复杂的、多方面的，需要采取细致入微的方法来应对这些国家所面临的独特情况和挑战。</p><h3 id="专有软件交易" tabindex="-1">专有软件交易 <a class="header-anchor" href="#专有软件交易" aria-label="Permalink to “专有软件交易”">​</a></h3><p>美国和欧洲的科技巨头与发展中地区的政府签订了价值数十亿美元、长达数十年的软件供应协议。一旦有人当选，并决定开始采用开源软件，他们就会发现摆脱这些交易需要付出巨大的代价。</p><h3 id="开源并非一帆风顺" tabindex="-1">开源并非一帆风顺 <a class="header-anchor" href="#开源并非一帆风顺" aria-label="Permalink to “开源并非一帆风顺”">​</a></h3><p>这些只是开放源代码在发展中国家面临的一些困难。要改善这种状况，使开源技术的采用和发展变得可行，还有许多工作要做。在今后的文章中，我将深入探讨具体的解决方案，但现在，我想说的是，任何事情都要从个人做起。当我们每个人都 “众包” 开放文化时，我们生活和工作所在地区的文化也会随之改变。尽你所能，将开放源代码带入你的社区，看看它会带来什么。</p><p><em>（题图：MJ/e9f5a8be-b0bd-425a-8199-248f5c0abe16）</em></p><hr>',13)),l("p",null,[e[8]||(e[8]=a("via: ",-1)),r(t,{href:"https://opensource.com/article/23/4/challenges-open-source-developing-countries"},{default:n(()=>[...e[7]||(e[7]=[a("https://opensource.com/article/23/4/challenges-open-source-developing-countries",-1)])]),_:1})]),l("p",null,[e[13]||(e[13]=a("作者：",-1)),r(t,{href:"https://opensource.com/users/ahmed-sobeh"},{default:n(()=>[...e[9]||(e[9]=[a("Ahmed Sobeh",-1)])]),_:1}),e[14]||(e[14]=a(" 选题：",-1)),r(t,{href:"https://github.com/lkxed/"},{default:n(()=>[...e[10]||(e[10]=[a("lkxed",-1)])]),_:1}),e[15]||(e[15]=a(" 译者：",-1)),r(t,{href:"https://github.com/wcjjdlhws"},{default:n(()=>[...e[11]||(e[11]=[a("wcjjdlhws",-1)])]),_:1}),e[16]||(e[16]=a(" 校对：",-1)),r(t,{href:"https://github.com/wxy"},{default:n(()=>[...e[12]||(e[12]=[a("wxy",-1)])]),_:1})]),l("p",null,[e[19]||(e[19]=a("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[17]||(e[17]=[a("LCTT",-1)])]),_:1}),e[20]||(e[20]=a(" 原创编译，",-1)),r(t,{href:"https://linux.cn/"},{default:n(()=>[...e[18]||(e[18]=[a("Linux中国",-1)])]),_:1}),e[21]||(e[21]=a(" 荣誉推出",-1))])])}const C=i(u,[["render",h]]);export{P as __pageData,C as default};
